(()=>{'use strict';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let generation=0;
const titles={backups:'数据备份与恢复',permissions:'角色权限配置',monitor:'运行监控',content:'内容管理'};
const notes={backups:'本机 MySQL 一致性 JSON 备份包含业务与附件；恢复保留当前账号、权限、审计及本机密钥，并保留单据序号高水位。仅支持本机生成的备份，不提供账号认证信息下载。恢复前自动备份，成功后全部会话失效。',permissions:'设置服务人员与审核员的功能开关，只能在原岗位允许范围内收紧权限。管理员管理权限固定保留，审核员不能获得客服会话权限。',monitor:'运行时长、请求量与服务错误数自本次进程启动累计。错误数仅统计服务器异常；内存为 JVM 已用堆内存；数据库大小为 MySQL 表和索引的估算字节。SQLite WAL 不适用，兼容字段显示 0。数据库检查验证连接与表访问，不代表完整磁盘一致性检查。业务条数按 records.kind 分组，附件按 files 记录计数。点击刷新读取最新值。',content:'管理客户端设备选购首页的公告与服务信息。保存为未发布时不展示；勾选发布后客户端刷新生效。仅支持纯文本，不执行HTML或脚本。'};
function design(tab){return `<details class="panel"><summary>${titles[tab]}功能设计说明</summary><p>设计价值：让管理员在后台维护${titles[tab]}，减少手动文件操作。</p><p>${notes[tab]}</p><p>仅管理员可访问与保存，接口再次校验角色。配置存入 MySQL settings 记录；提交校验格式，权限和内容采用 revision 防止并发覆盖。失败会显示错误并保留可重试入口。备份使用 MySQL 一致性事务导出 JSON 与 SHA-256 校验，恢复使用事务；运行监控不提供虚构历史趋势。</p><footer>原型来源方：SDMC-IT</footer></details>`;}
async function render(host,tab,token){const epoch=++generation;const call=async(name,body)=>{const r=await fetch('/api/admin/tools/'+name,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},...(body===undefined?{}:{body:JSON.stringify(body)})});const d=await r.json();if(!r.ok)throw Error(d.error||'操作失败');return d;};host.innerHTML='<p>正在加载…</p>';try{const d=await call(tab);if(epoch!==generation||!host.isConnected)return;let html='';
if(tab==='backups'){html=`<button class="btn primary" data-tool="backup">创建本机备份</button><p>${notes.backups}</p><div class="table-wrap"><table><thead><tr><th>时间</th><th>类型</th><th>大小</th><th>操作</th></tr></thead><tbody>${d.backups.map(b=>`<tr><td>${esc(new Date(b.createdAt).toLocaleString())}</td><td>${esc(b.reason)}</td><td>${(b.size/1048576).toFixed(2)} MB</td><td><button class="btn" data-tool="preview" data-id="${esc(b.id)}">校验 / 恢复</button></td></tr>`).join('')||'<tr><td colspan="4">暂无备份</td></tr>'}</tbody></table></div><div id="restorePreview"></div>`;}
if(tab==='permissions'){const names={projects:'售前需求',orders:'售中订单',tickets:'售后维保',chat:'客服会话',followups:'跟进任务'};html=`<form data-tool-form="permissions"><p>${notes.permissions}</p><input type="hidden" name="revision" value="${d.config.revision}"><div class="table-wrap"><table><thead><tr><th>功能</th><th>服务人员</th><th>审核员</th></tr></thead><tbody>${d.capabilities.map(k=>`<tr><td>${names[k]}</td>${['service','reviewer'].map(r=>`<td><input type="checkbox" aria-label="${r==='service'?'服务人员':'审核员'}${names[k]}" name="${r}.${k}" ${d.config.roles[r][k]?'checked':''} ${r==='reviewer'&&k==='chat'?'disabled':''}></td>`).join('')}</tr>`).join('')}</tbody></table></div><button class="btn primary">保存权限配置</button></form>`;}
if(tab==='monitor'){html=`<p>采样时间：${esc(new Date(d.at).toLocaleString())}</p><div class="stats">${[['运行时长',d.uptimeSeconds+' 秒'],['请求总量',d.requests],['服务错误',d.errors],['JVM 已用堆内存',(d.memoryBytes/1048576).toFixed(1)+' MB'],['数据库（估算）',(d.databaseBytes/1048576).toFixed(2)+' MB'],['SQLite WAL（不适用）',(d.walBytes/1048576).toFixed(2)+' MB'],['附件数量',d.attachments],['本机备份',d.backupCount]].map(([n,v])=>`<div class="stat"><span>${n}</span><strong>${v}</strong></div>`).join('')}</div><p>数据库连接与表访问检查：${esc(d.integrity)}</p><div class="table-wrap"><table><thead><tr><th>数据类型</th><th>记录数</th></tr></thead><tbody>${d.counts.map(c=>`<tr><td>${esc(({order:'订单',project:'售前需求',ticket:'维保工单',customer:'客户账号',user:'员工账号',conversation:'业务会话',supportChat:'在线咨询',settings:'系统设置',product:'产品维护',followup:'跟进任务'})[c.kind]||c.kind)}</td><td>${c.count}</td></tr>`).join('')}</tbody></table></div>`;}
if(tab==='content'){const c=d.content;html=`<form data-tool-form="content"><input type="hidden" name="revision" value="${c.revision}">${[['title','公告标题',60],['announcement','公告正文',1000],['contact','服务联系方式',100],['hours','服务时间',100]].map(([k,n,max])=>`<label class="field"><span>${n}</span>${k==='announcement'?`<textarea name="${k}" maxlength="${max}" rows="4">${esc(c[k])}</textarea>`:`<input name="${k}" maxlength="${max}" value="${esc(c[k])}">`}</label>`).join('')}<label class="check"><input type="checkbox" name="published" ${c.published?'checked':''}>发布到客户端首页</label><p>${notes.content}</p><button class="btn primary">保存内容</button></form>`;}
host.innerHTML=`<article class="panel">${html}<p class="tool-status" role="status"></p></article>${design(tab)}`;
host.onclick=async e=>{const b=e.target.closest('[data-tool]');if(!b)return;b.disabled=true;const status=host.querySelector('.tool-status');try{if(b.dataset.tool==='backup'){await call('backups',{});await render(host,tab,token);}if(b.dataset.tool==='preview'){const v=await call('restore-preview',{id:b.dataset.id});host.querySelector('#restorePreview').innerHTML=`<form data-tool-form="restore"><h3>恢复前确认</h3><p>备份时间：${esc(new Date(v.backup.createdAt).toLocaleString())}。备份中共有${v.counts.reduce((n,c)=>n+c.count,0)}条记录。业务数据将回到该时间点，账号、权限和审计保留当前状态。</p><input type="hidden" name="id" value="${esc(v.backup.id)}"><label class="field">输入“恢复数据”确认<input name="confirm" required autocomplete="off"></label><button class="btn">确认恢复</button></form>`;}}catch(e){status.textContent=e.message;}finally{b.disabled=false;}};
host.onsubmit=async e=>{const f=e.target.closest('[data-tool-form]');if(!f)return;e.preventDefault();const b=f.querySelector('button'),status=host.querySelector('.tool-status');b.disabled=true;const data=Object.fromEntries(new FormData(f));try{const name=f.dataset.toolForm;if(name==='permissions'){data.revision=Number(data.revision);data.roles={};for(const r of ['service','reviewer']){data.roles[r]={};for(const k of d.capabilities)data.roles[r][k]=f.elements[r+'.'+k].checked;}await call(name,data);}else if(name==='content'){data.revision=Number(data.revision);data.published=f.elements.published.checked;await call(name,data);}else{await call('restore',data);host.innerHTML='<article class="panel"><h2>恢复成功</h2><p>已保留恢复前备份。请刷新页面，重新登录后使用。</p></article>';return;}await render(host,tab,token);host.querySelector('.tool-status').textContent='已保存';}catch(e){status.textContent=e.message;}finally{b.disabled=false;}};
}catch(e){if(epoch===generation&&host.isConnected){host.textContent=e.message;}}}
let site=null;
async function loadSite(){try{site=(await(await fetch('/api/site-content')).json()).content;applySite();}catch{}}
function applySite(){if(location.search.includes('workspace=staff')||!['','#catalog'].includes(location.hash))return;const main=document.querySelector('#main');if(!main||!document.querySelector('#catalogSearch')||main.querySelector('[data-site-content]')||!site)return;const box=document.createElement('section');box.className='wrap';box.dataset.siteContent='';box.innerHTML=`<article class="notice"><strong>${esc(site.title)}</strong><p style="white-space:pre-wrap">${esc(site.announcement)}</p><p>${esc(site.contact)}${site.hours?' · '+esc(site.hours):''}</p></article>`;main.prepend(box);}
new MutationObserver(applySite).observe(document.querySelector('#main'),{childList:true});window.addEventListener('hashchange',loadSite);void loadSite();
window.SanyAdminTools={render,stop:()=>generation++};
})();
